CREATE TABLE `analise_planos_referencias_normam` (
  `id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `categoria` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `norma` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NORMAM-202',
  `item_norma` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `referencia_normativa` text COLLATE utf8mb4_general_ci NOT NULL,
  `titulo` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `descricao_padrao` text COLLATE utf8mb4_general_ci NOT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `ordem` int unsigned NOT NULL DEFAULT '0',
  `criado_por` char(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `criado_em` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `atualizado_em` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_normam_categoria` (`categoria`,`ativo`),
  FULLTEXT KEY `idx_normam_busca` (`titulo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
